cd /workspace/nox/web/site; [ -f music.html.bak_w3_1 ] || cp music.html music.html.bak_w3_1
echo '' | base64 -d | gunzip > nox-music-x.js
echo '' | base64 -d | gunzip > nox-music-x.css
python3 - <<'P'
p='/workspace/nox/web/site/music.html'; s=open(p,encoding='utf-8').read()
if 'nox-music-x' not in s:
    s=s.replace('</head>','<link rel="stylesheet" href="./vendor/swiper/swiper-bundle.min.css">\n<link rel="stylesheet" href="./nox-music-x.css?v=1">\n</head>',1).replace('</body>','<script type="module" src="./nox-music-x.js?v=1"></script>\n</body>',1)
    open(p,'w',encoding='utf-8').write(s); print('patched')
P
echo '' | base64 -d | gunzip > /tmp/w3s.py
/workspace/nox/venv/bin/python /tmp/w3s.py musicA http://127.0.0.1:8091/web/music.html 2>&1
